&lt;span id=&#34;cb1-8&#34;&gt;&lt;a href=&#34;#cb1-8&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;    mat&lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;dt&#34;&gt;int&lt;/span&gt; n1&lt;span class=&#34;op&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;dt&#34;&gt;int&lt;/span&gt; m1&lt;span class=&#34;op&#34;&gt;):&lt;/span&gt; n&lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;n1&lt;span class=&#34;op&#34;&gt;),&lt;/span&gt; m&lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;m1&lt;span class=&#34;op&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/span&gt;
