&lt;span id=&#34;cb10-258&#34;&gt;&lt;a href=&#34;#cb10-258&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;    &lt;span class=&#34;bu&#34;&gt;std::&lt;/span&gt;sort&lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;qid&lt;span class=&#34;op&#34;&gt;.&lt;/span&gt;begin&lt;span class=&#34;op&#34;&gt;(),&lt;/span&gt; qid&lt;span class=&#34;op&#34;&gt;.&lt;/span&gt;end&lt;span class=&#34;op&#34;&gt;(),&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;[&amp;amp;](&lt;/span&gt;&lt;span class=&#34;dt&#34;&gt;int&lt;/span&gt; x&lt;span class=&#34;op&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;dt&#34;&gt;int&lt;/span&gt; y&lt;span class=&#34;op&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;#123;&lt;/span&gt; &lt;span class=&#34;cf&#34;&gt;return&lt;/span&gt; a&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;x&lt;span class=&#34;op&#34;&gt;]&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;lt;&lt;/span&gt; a&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;y&lt;span class=&#34;op&#34;&gt;];&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;#125;);&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb10-259&#34;&gt;&lt;a href=&#34;#cb10-259&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;    &lt;span class=&#34;bu&#34;&gt;std::&lt;/span&gt;sort&lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;nid&lt;span class=&#34;op&#34;&gt;.&lt;/span&gt;begin&lt;span class=&#34;op&#34;&gt;(),&lt;/span&gt; nid&lt;span class=&#34;op&#34;&gt;.&lt;/span&gt;end&lt;span class=&#34;op&#34;&gt;(),&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;[&amp;amp;](&lt;/span&gt;&lt;span class=&#34;dt&#34;&gt;int&lt;/span&gt; x&lt;span class=&#34;op&#34;&gt;,&lt;/span&gt; &lt;span class=&#34;dt&#34;&gt;int&lt;/span&gt; y&lt;span class=&#34;op&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;#123;&lt;/span&gt; &lt;span class=&#34;cf&#34;&gt;return&lt;/span&gt; lim&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;x&lt;span class=&#34;op&#34;&gt;]&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;gt;&lt;/span&gt; lim&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;y&lt;span class=&#34;op&#34;&gt;];&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;#125;);&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb10-260&#34;&gt;&lt;a href=&#34;#cb10-260&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;    &lt;span class=&#34;cf&#34;&gt;for&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;&lt;span class=&#34;kw&#34;&gt;auto&lt;/span&gt; i &lt;span class=&#34;op&#34;&gt;:&lt;/span&gt; qid&lt;span class=&#34;op&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb10-261&#34;&gt;&lt;a href=&#34;#cb10-261&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;        &lt;span class=&#34;cf&#34;&gt;for&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;(;&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;!&lt;/span&gt;nid&lt;span class=&#34;op&#34;&gt;.&lt;/span&gt;empty&lt;span class=&#34;op&#34;&gt;()&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;amp;&amp;amp;&lt;/span&gt; lim&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;nid&lt;span class=&#34;op&#34;&gt;.&lt;/span&gt;back&lt;span class=&#34;op&#34;&gt;()]&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;lt;&lt;/span&gt; a&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;i&lt;span class=&#34;op&#34;&gt;];&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;#123;&lt;/span&gt;&lt;/span&gt;
