&lt;span id=&#34;cb10-272&#34;&gt;&lt;a href=&#34;#cb10-272&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;        res&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;i&lt;span class=&#34;op&#34;&gt;]&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;=&lt;/span&gt; t&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;rt&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;p&lt;span class=&#34;op&#34;&gt;]].&lt;/span&gt;u&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;&lt;span class=&#34;dv&#34;&gt;0&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;][&lt;/span&gt;&lt;span class=&#34;dv&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;];&lt;/span&gt;&lt;/span&gt;
