&lt;span id=&#34;cb4-12&#34;&gt;&lt;a href=&#34;#cb4-12&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;    &lt;span class=&#34;bu&#34;&gt;std::&lt;/span&gt;cin &lt;span class=&#34;op&#34;&gt;&amp;gt;&amp;gt;&lt;/span&gt; n &lt;span class=&#34;op&#34;&gt;&amp;gt;&amp;gt;&lt;/span&gt; k&lt;span class=&#34;op&#34;&gt;;&lt;/span&gt;&lt;/span&gt;
