&lt;span id=&#34;cb8-90&#34;&gt;&lt;a href=&#34;#cb8-90&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;            &lt;span class=&#34;cf&#34;&gt;if&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;cnt &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;la &lt;span class=&#34;op&#34;&gt;==&lt;/span&gt; &lt;span class=&#34;dv&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; l0 &lt;span class=&#34;op&#34;&gt;&amp;lt;=&lt;/span&gt; k &lt;span class=&#34;op&#34;&gt;&amp;amp;&amp;amp;&lt;/span&gt; cnt &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;la &lt;span class=&#34;op&#34;&gt;==&lt;/span&gt; &lt;span class=&#34;dv&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; r0 &lt;span class=&#34;op&#34;&gt;&amp;gt;=&lt;/span&gt; k &lt;span class=&#34;op&#34;&gt;&amp;amp;&amp;amp;&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;(!&lt;/span&gt;p0 &lt;span class=&#34;op&#34;&gt;||&lt;/span&gt; cnt &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;la &lt;span class=&#34;op&#34;&gt;==&lt;/span&gt; &lt;span class=&#34;dv&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; p0 &lt;span class=&#34;op&#34;&gt;!=&lt;/span&gt; k&lt;span class=&#34;op&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;amp;&amp;amp;&lt;/span&gt; DFS&lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;x &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; &lt;span class=&#34;dv&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;,&lt;/span&gt; cnt &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;la &lt;span class=&#34;op&#34;&gt;==&lt;/span&gt; &lt;span class=&#34;dv&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; a&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;x&lt;span class=&#34;op&#34;&gt;],&lt;/span&gt; &lt;span class=&#34;dv&#34;&gt;0&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;))&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb8-91&#34;&gt;&lt;a href=&#34;#cb8-91&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;                res&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;x&lt;span class=&#34;op&#34;&gt;]&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;=&lt;/span&gt; &lt;span class=&#34;dv&#34;&gt;0&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;;&lt;/span&gt;&lt;/span&gt;
&lt;span id=&#34;cb8-92&#34;&gt;&lt;a href=&#34;#cb8-92&#34; aria-hidden=&#34;true&#34; tabindex=&#34;-1&#34;&gt;&lt;/a&gt;            &lt;span class=&#34;cf&#34;&gt;else&lt;/span&gt; &lt;span class=&#34;cf&#34;&gt;if&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;cnt &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;!&lt;/span&gt;la &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; l1 &lt;span class=&#34;op&#34;&gt;&amp;lt;=&lt;/span&gt; k &lt;span class=&#34;op&#34;&gt;&amp;amp;&amp;amp;&lt;/span&gt; cnt &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;!&lt;/span&gt;la &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; r1 &lt;span class=&#34;op&#34;&gt;&amp;gt;=&lt;/span&gt; k &lt;span class=&#34;op&#34;&gt;&amp;amp;&amp;amp;&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;(!&lt;/span&gt;p1 &lt;span class=&#34;op&#34;&gt;||&lt;/span&gt; cnt &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;!&lt;/span&gt;la &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; p1 &lt;span class=&#34;op&#34;&gt;!=&lt;/span&gt; k&lt;span class=&#34;op&#34;&gt;)&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;&amp;amp;&amp;amp;&lt;/span&gt; DFS&lt;span class=&#34;op&#34;&gt;(&lt;/span&gt;x &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; &lt;span class=&#34;dv&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;,&lt;/span&gt; cnt &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;!&lt;/span&gt;la &lt;span class=&#34;op&#34;&gt;+&lt;/span&gt; &lt;span class=&#34;op&#34;&gt;!&lt;/span&gt;a&lt;span class=&#34;op&#34;&gt;[&lt;/span&gt;x&lt;span class=&#34;op&#34;&gt;],&lt;/span&gt; &lt;span class=&#34;dv&#34;&gt;1&lt;/span&gt;&lt;span class=&#34;op&#34;&gt;))&lt;/span&gt;&lt;/span&gt;
